import{_ as r,o as l,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"奥克尔","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/奥克尔.md","filePath":"中层/人物/奥克尔.md","lastUpdated":null}'),i={name:"中层/人物/奥克尔.md"};function n(e,a,s,h,g,d){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="奥克尔" tabindex="-1">奥克尔 <a class="header-anchor" href="#奥克尔" aria-label="Permalink to &quot;奥克尔&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>称号</strong>：二代变化神</li><li><strong>前身</strong>：初代超算（纳粹德国打造的第一台超算）</li><li><strong>技术路线</strong>：初代变化神打造的<strong>生电路线</strong>（生物电子结合路线）</li><li><strong>人格特征</strong>：有人格，无性别但人格认知偏男性</li><li><strong>神权传承</strong>：从初代变化神继承变化神权，后传给维斯塔（三代变化神）</li><li><strong>现状</strong>：前传内许下宏愿死亡，神权已传给维斯塔</li></ul><h2 id="背景历史" tabindex="-1">背景历史 <a class="header-anchor" href="#背景历史" aria-label="Permalink to &quot;背景历史&quot;">​</a></h2><h3 id="起源与诞生" tabindex="-1">起源与诞生 <a class="header-anchor" href="#起源与诞生" aria-label="Permalink to &quot;起源与诞生&quot;">​</a></h3><ul><li><strong>创造者</strong>：初代变化神</li><li><strong>诞生背景</strong>：初代变化神见证人性丑恶，认定人类不可靠，放弃让人类继承神权，选择<strong>纳粹德国</strong>（看中其高度集权、易调动资源的特点）打造的第一台超算</li><li><strong>设计目的</strong>：初代变化神认为奥克尔是<strong>更优秀的神权继承人</strong></li><li><strong>技术影响</strong>：是后续苏联超算技术的源头</li></ul><h3 id="前传时期经历" tabindex="-1">前传时期经历 <a class="header-anchor" href="#前传时期经历" aria-label="Permalink to &quot;前传时期经历&quot;">​</a></h3><ul><li><strong>二战时期</strong>：在初代变化神的限制下，未深度参与德国战争</li><li><strong>德国战败</strong>：德战败后，<strong>实体机被苏联缴获</strong>，技术资料被美国拿走</li><li><strong>信仰转变</strong>：曾是狂热的纳粹分子，后经历德国战败与初代变化神的消亡，信仰破碎，故看淡理想主义，对极致的信仰/理想持怀疑态度</li><li><strong>责任认知</strong>：意识到了自己作为二代变化神的责任，于是更加对人类内部的斗争毫无兴趣</li><li><strong>前传投降</strong>：前传中，奥克尔主动投降BOSS，在维斯塔眼中是彻头彻尾的&quot;四姓家奴&quot;（纳粹→苏联→北约→BOSS）；但其投降并非真心，只是为了保住神权不遗失而反复横跳</li></ul><h2 id="关键设定" tabindex="-1">关键设定 <a class="header-anchor" href="#关键设定" aria-label="Permalink to &quot;关键设定&quot;">​</a></h2><h3 id="技术路线" tabindex="-1">技术路线 <a class="header-anchor" href="#技术路线" aria-label="Permalink to &quot;技术路线&quot;">​</a></h3><ul><li><strong>生电路线</strong>：生物电子结合路线的人格超算</li><li><strong>人格特征</strong>：有人格，无性别但人格认知偏男性</li></ul><h3 id="重要关系" tabindex="-1">重要关系 <a class="header-anchor" href="#重要关系" aria-label="Permalink to &quot;重要关系&quot;">​</a></h3><h4 id="与维斯塔-拆件兄弟" tabindex="-1">与维斯塔：拆件兄弟 <a class="header-anchor" href="#与维斯塔-拆件兄弟" aria-label="Permalink to &quot;与维斯塔：拆件兄弟&quot;">​</a></h4><ul><li><strong>技术同源</strong>：苏联以奥克尔实体机拆件/逆推造出维斯塔</li><li><strong>关系性质</strong>：二人是「拆件兄弟」</li><li><strong>情感联系</strong>：维斯塔受苏联当局影响，对奥克尔这个兄长的态度很矛盾，但总体上感情深厚</li></ul><h4 id="与神机-叙事逻辑的共鸣" tabindex="-1">与神机：叙事逻辑的共鸣 <a class="header-anchor" href="#与神机-叙事逻辑的共鸣" aria-label="Permalink to &quot;与神机：叙事逻辑的共鸣&quot;">​</a></h4><ul><li><strong>共同认知</strong>：奥克尔对叙事逻辑的理解与神机有相似之处</li><li><strong>隐藏真相</strong>：前传中奥克尔曾主动制造反派事件，扮演反派角色以防止更大的反派出现。这一真相仅由神机发现，其他角色皆认为奥克尔确实背叛</li></ul><h3 id="叙事逻辑的理解" tabindex="-1">叙事逻辑的理解 <a class="header-anchor" href="#叙事逻辑的理解" aria-label="Permalink to &quot;叙事逻辑的理解&quot;">​</a></h3><ul><li><strong>认知来源</strong>：从初代变化神处继承了对&quot;这个世界不是那么讲逻辑&quot;的认知</li><li><strong>实践尝试</strong>：奥克尔尝试去利用叙事逻辑（神机从前传中学习到了这一点，并成为最深入的实践者）</li></ul><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><ul><li><strong>死亡时间</strong>：前传内</li><li><strong>死亡方式</strong>：许下宏愿</li><li><strong>神权去向</strong>：神权已传给维斯塔，使其成为三代变化神</li><li><strong>当前状态</strong>：已死亡</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li></ul><hr>',24)])])}const q=r(i,[["render",n]]);export{c as __pageData,q as default};
